script_old = "Eu sou o prefeito de uma cidade com zero moradores. Prazer, Capivaldo! Aqui não tem casa... não tem rua... não tem nem gente. E a partir de hoje, quem manda nessa cidade é você. Seguiu o perfil? Você vira morador. Comentou? Ganha um terreno com o seu arroba na placa. E curte esse vídeo, pra ele chegar em mais gente pra ajudar a construir. Tudo aqui é decidido nos comentários. Primeira votação: o que a cidade ganha primeiro? A: Pizzaria. Ninguém constrói uma cidade com fome. B: Lagoa. Cidade de capivara sem lagoa? Não dá. Comenta só a letra. A mais votada vira obra no próximo vídeo. Segue agora pra garantir a sua casa... senão..."
script = "Ela disse: vou parar de te seguir, quero ser a prefeita! CALMA! A cidade realizou! Prefeita nova, com a prefeitura e tudo! E uma segunda seguidora também pediu pra ser prefeita... então agora são duas! Cidade do Insta, episódio trinta e dois: mais de dezesseis mil moradores! E vamos de desejos! O dono do fliperama chegou! O policial! Dois jogadores de futebol famosos! E o monstro que assombra a floresta de noite, no terceiro pedido do Thalles! A menina com cachorrinha e casinha rosa! A engenheira! A gatinha! E os presidentes! Mas ó, atenção! Hoje eu realizei os desejos dos comentários porque ainda não chegou nenhum pedido novo pelo site. Daqui pra frente, só vou realizar os pedidos feitos pelo link da bio! É só entrar na loja, escrever o seu desejo em Pedido no vídeo, a partir de dez reais, só cinco vagas por semana! E quem comenta, curte e republica ganha casa! Só comentou? Casa ruim. Seguiu? Casa legal. E quem comentou, curtiu e republicou... ganha uma MANSÃO! Quer a sua? Comenta, curte e republica! A vigésima quinta votação ainda está aberta: cafeteria ou quadra de basquete! E agora a vigésima sexta: A, floresta assombrada, ou B, estádio de futebol? Comenta a letra... senão o monstro assombra a sua casa!"
toks = script.split()
def norm(t): return ''.join(c for c in unicodedata.normalize('NFD',t.lower()) if c.isalnum())
W = json.load(open('/home/user/ep32/work/words.json'))
wn = [norm(w['w']) for w in W]; sn=[norm(t) for t in toks]
sm = difflib.SequenceMatcher(None, sn, wn, autojunk=False)
times=[None]*len(toks)
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag=='equal':
        for k in range(i2-i1): times[i1+k]=(W[j1+k]['s'],W[j1+k]['e'])
    elif tag=='replace':
        s=W[j1]['s']; e=W[j2-1]['e']; n=i2-i1
        for k in range(n): times[i1+k]=(s+(e-s)*k/n, s+(e-s)*(k+1)/n)
# fill gaps
for i,t in enumerate(times):
    if t is None:
        p=times[i-1][1] if i else 0
        times[i]=(p,p+0.2)
